#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


VAULT="PETA"
REPO="iseft/peta"
# Nothing in this wizard writes a .env directly: secrets go to 1Password and
# `pnpm env:pull` renders apps/api/.env and apps/web/.env from them.
ENV_FILE="/dev/null/no-env-file"

cd "$(dirname "$0")/.."

# One 1Password item per service, one field per key: op://PETA/<item>/<field>.
# The Clerk development keys use the labels the item was created with
# (CLERK_SECRET_KEY, NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY); production keys get a
# _PROD suffix.
CLERK_ITEM="Clerk"
PAYLOAD_ITEM="Payload"

# save_fields ITEM LABEL=VALUE... sets those fields on a 1Password item,
# creating the item if needed and leaving every other field as it was:
# re-running a stage must never drop keys saved earlier. Labels containing
# SECRET, secret or password are stored concealed. Values pass through stdin and
# a private temp file, never the command line or the environment, so they can't
# show up in `ps`.
save_fields() {
  local item="$1" tmp mode
  shift
  tmp=$(umask 077 && mktemp)
  if op item get "$item" --vault "$VAULT" --format json > "$tmp" 2>/dev/null; then
    mode=edit
  else
    printf '{"title":"%s","category":"API_CREDENTIAL","fields":[]}' "$item" > "$tmp"
    mode=create
  fi
  printf '%s\n' "$@" | node -e '
    const fs = require("fs");
    const item = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
    item.fields = item.fields || [];
    for (const line of fs.readFileSync(0, "utf8").split("\n").filter(Boolean)) {
      const at = line.indexOf("=");
      const label = line.slice(0, at), value = line.slice(at + 1);
      const type = /secret|password/i.test(label) ? "CONCEALED" : "STRING";
      const field = item.fields.find((f) => f.label === label);
      if (field) Object.assign(field, { value, type });
      else item.fields.push({ id: label, label, type, value });
    }
    fs.writeFileSync(process.argv[1], JSON.stringify(item));' "$tmp"
  if [[ "$mode" == edit ]]; then
    op item edit "$item" --vault "$VAULT" --template "$tmp" >/dev/null
  else
    op item create --vault "$VAULT" --template "$tmp" >/dev/null
  fi
  rm -f "$tmp"
  printf '  %s✓ saved%s %s → 1Password item %s\n' "$GREEN" "$RESET" "${*%%=*}" "$item"
}

# has_field ITEM LABEL succeeds when the item already holds a non-empty LABEL.
has_field() {
  [[ -n "$(op read "op://$VAULT/$1/$2" 2>/dev/null || true)" ]]
}

# wait_for_health URL polls until it answers 200 or gives up after ~60s.
wait_for_health() {
  local url="$1" i
  for i in $(seq 1 30); do
    if [[ "$(curl -s -o /dev/null -w '%{http_code}' "$url" || true)" == "200" ]]; then
      printf '  %s✓ healthy%s %s\n' "$GREEN" "$RESET" "$url"
      return 0
    fi
    sleep 2
  done
  warn "no 200 from $url"
  return 1
}

run_wizard() {

TOTAL_STAGES=9

banner "Peta: 1Password, Clerk, Railway"

stage "1Password: vault"
for cmd in op railway gh pnpm docker curl node openssl; do
  command -v "$cmd" >/dev/null 2>&1 || { warn "$cmd is not installed"; exit 1; }
done
# `op whoami` reports "not signed in" under the 1Password desktop-app
# integration until some command has triggered the unlock prompt, so ask for
# something that triggers it instead.
if ! op vault list >/dev/null 2>&1; then
  say "Sign in to the 1Password CLI first:"
  step "Unlock the 1Password app (or run: eval \$(op signin)), then re-run this wizard."
  exit 1
fi
if op vault get "$VAULT" >/dev/null 2>&1; then
  printf '  %s✓ vault exists%s %s\n' "$GREEN" "$RESET" "$VAULT"
elif confirm "Create the 1Password vault \"$VAULT\"?"; then
  op vault create "$VAULT" >/dev/null
  printf '  %s✓ created vault%s %s\n' "$GREEN" "$RESET" "$VAULT"
else
  warn "the rest of the wizard needs the vault"; exit 1
fi
pause

stage "Clerk: API keys"
if has_field "$CLERK_ITEM" CLERK_SECRET_KEY; then
  printf '  %s✓ development keys saved%s\n' "$GREEN" "$RESET"
else
  say "Copy the Development instance keys of the Clerk application \"PETA\"."
  open_url "https://dashboard.clerk.com/"
  ask CLERK_PUBLISHABLE_KEY_DEV "Development Publishable key (pk_test_…):"
  ask_secret CLERK_SECRET_KEY_DEV "Development Secret key (sk_test_…):"
  [[ "$CLERK_SECRET_KEY_DEV" == sk_test_* ]] || { warn "that isn't a development secret key (sk_test_…)"; exit 1; }
  save_fields "$CLERK_ITEM" "NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY=$CLERK_PUBLISHABLE_KEY_DEV" "CLERK_SECRET_KEY=$CLERK_SECRET_KEY_DEV"
fi
if has_field "$CLERK_ITEM" CLERK_SECRET_KEY_PROD; then
  printf '  %s✓ production keys saved%s\n' "$GREEN" "$RESET"
else
  note "Railway runs against the Production instance. No production instance yet? Press Enter; stage 8 will stop until one exists."
  open_url "https://dashboard.clerk.com/"
  step "Switch the PETA application to its Production instance and open API keys."
  ask CLERK_PUBLISHABLE_KEY_PROD "Production Publishable key (pk_live_…, Enter to skip):" || true
  if [[ -n "${CLERK_PUBLISHABLE_KEY_PROD:-}" ]]; then
    ask_secret CLERK_SECRET_KEY_PROD "Production Secret key (sk_live_…):"
    [[ "$CLERK_SECRET_KEY_PROD" == sk_live_* ]] || { warn "that isn't a production secret key (sk_live_…)"; exit 1; }
    save_fields "$CLERK_ITEM" "CLERK_PUBLISHABLE_KEY_PROD=$CLERK_PUBLISHABLE_KEY_PROD" "CLERK_SECRET_KEY_PROD=$CLERK_SECRET_KEY_PROD"
  fi
fi
note "Publishable keys go into the mobile app; they are not secrets."
pause

stage "1Password: Payload secrets"
say "The marketing site's CMS needs random secrets; this generates any that are missing."
missing=()
for label in payload_secret_local revalidate_secret_local admin_password_local payload_secret_prod revalidate_secret_prod admin_password_prod; do
  has_field "$PAYLOAD_ITEM" "$label" || missing+=("$label=$(openssl rand -hex 32)")
done
if (( ${#missing[@]} )); then
  save_fields "$PAYLOAD_ITEM" "${missing[@]}"
else
  printf '  %s✓ all Payload secrets saved%s\n' "$GREEN" "$RESET"
fi
if ! has_field "$PAYLOAD_ITEM" admin_email_prod; then
  ask ADMIN_EMAIL_PROD "Email for the production CMS admin:"
  save_fields "$PAYLOAD_ITEM" "admin_email_prod=$ADMIN_EMAIL_PROD"
fi
pause

stage "Local: pull env and check the API boots"
pnpm run env:pull
pnpm run db:up >/dev/null
pnpm run build >/dev/null
( cd apps/api && pnpm run prisma:deploy >/dev/null && npx dotenv -e .env -- node dist/seed/seed.js >/dev/null )
say "Booting the API against local Postgres…"
( cd apps/api && npx dotenv -e .env -- node dist/main >/tmp/peta-wizard-api.log 2>&1 ) &
API_PID=$!
if wait_for_health "http://localhost:3000/api/health"; then
  kill "$API_PID" 2>/dev/null || true
else
  kill "$API_PID" 2>/dev/null || true
  warn "the API didn't come up; see /tmp/peta-wizard-api.log"; exit 1
fi
pause

stage "GitHub: scaffold on main"
say "Railway deploys from main, so the scaffold must be pushed before Railway is set up."
if gh api "repos/$REPO/contents/apps/api/package.json?ref=main" >/dev/null 2>&1; then
  printf '  %s✓ main has the api app%s\n' "$GREEN" "$RESET"
else
  warn "main doesn't have the api app yet."
  step "Push the scaffold to main, then re-run this wizard."
  note "Earlier stages are safe to repeat: saved values are kept."
  exit 1
fi
pause

stage "Railway: project"
if ! railway whoami >/dev/null 2>&1; then
  say "Logging in to Railway (a browser window opens)."
  railway login
fi
if railway status >/dev/null 2>&1; then
  printf '  %s✓ this directory is already linked to a Railway project%s\n' "$GREEN" "$RESET"
  railway status
else
  say "Link this directory to the project's production environment (pick it from the list)."
  railway link
fi
pause

stage "Railway: apply infrastructure"
say ".railway/railway.ts declares the backend and web services, Postgres and the media bucket."
say "Applying it renames the project to \"peta\" and replaces the placeholder service \"peta\". Review the plan:"
railway config plan
note "If Railway can't see the repo, install the Railway GitHub app for $REPO first."
if confirm "Apply this plan to Railway?"; then
  railway config apply --yes --confirm-destructive
else
  warn "the rest of the wizard needs the services"; exit 1
fi
pause

stage "Railway: variables and domains"
railway variable set 'DATABASE_URL=${{Postgres.DATABASE_URL}}' NODE_ENV=production --service backend --skip-deploys >/dev/null
railway variable set 'DATABASE_URL=${{Postgres.DATABASE_URL}}' NODE_ENV=production --service web --skip-deploys >/dev/null
printf '  %s✓ set%s DATABASE_URL (reference to Postgres), NODE_ENV on backend and web\n' "$GREEN" "$RESET"
for pair in PAYLOAD_SECRET:payload_secret_prod REVALIDATE_SECRET:revalidate_secret_prod PAYLOAD_ADMIN_PASSWORD:admin_password_prod PAYLOAD_ADMIN_EMAIL:admin_email_prod; do
  op read "op://$VAULT/$PAYLOAD_ITEM/${pair#*:}" | railway variable set "${pair%%:*}" --stdin --service web --skip-deploys >/dev/null
done
printf '  %s✓ set%s Payload secrets on web (from 1Password)\n' "$GREEN" "$RESET"
if ! has_field "$CLERK_ITEM" CLERK_SECRET_KEY_PROD; then
  warn "1Password has no production Clerk secret key (CLERK_SECRET_KEY_PROD in item $CLERK_ITEM)."
  step "Create the Clerk Production instance, re-run this wizard and enter its keys in stage 2."
  exit 1
fi
op read "op://$VAULT/$CLERK_ITEM/CLERK_SECRET_KEY_PROD" \
  | railway variable set CLERK_SECRET_KEY --stdin --service backend >/dev/null
printf '  %s✓ set%s CLERK_SECRET_KEY (from 1Password)\n' "$GREEN" "$RESET"
for svc in backend web; do
  railway domain list --service "$svc" 2>/dev/null | grep -q 'railway.app' || railway domain --service "$svc"
done
ask WEB_DOMAIN "Paste the web domain Railway shows (e.g. web-production-xxxx.up.railway.app):"
railway variable set "NEXT_PUBLIC_SERVER_URL=https://${WEB_DOMAIN#https://}" --service web >/dev/null
ask API_DOMAIN "Paste the backend domain Railway shows (e.g. backend-production-xxxx.up.railway.app):"
say "Waiting for the deploy to go healthy (the first build takes a few minutes)…"
for _ in 1 2 3 4 5; do
  wait_for_health "https://${API_DOMAIN#https://}/api/health" && break
done || warn "not healthy yet; check the deploy logs in the Railway dashboard"
note "Put https://${API_DOMAIN#https://} into apps/mobile/src/config.ts as the production API URL."
pause

stage "Better Stack: error reporting (optional)"
say "Errors go to Better Stack through the Sentry SDK. Create two applications there"
say "(\"Peta API\" and \"Peta Mobile\") and save their DSNs in 1Password item"
say "\"Better Stack\" as api_dsn and mobile_dsn."
if has_field "Better Stack" api_dsn && confirm "Set BETTERSTACK_DSN on Railway now?"; then
  op read "op://$VAULT/Better Stack/api_dsn" | railway variable set BETTERSTACK_DSN --stdin --service backend >/dev/null
  printf '  %s✓ set%s BETTERSTACK_DSN on Railway\n' "$GREEN" "$RESET"
else
  note "Skipped. Re-run the wizard any time to add it."
fi
pause

finish
note "Local: apps/api/.env and apps/web/.env written by pnpm env:pull."
note "Railway: project \"peta\", services backend + web, Postgres, bucket media."
}

run_wizard "$@"; exit
